<?php require_once __DIR__.'/../../app/bootstrap.php';guard();$p=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$a=$_POST['a']??'';if($a==='add')$p->prepare("INSERT INTO services(category_id,name,description,price,sort_order)VALUES(?,?,?,?,?)")->execute([(int)$_POST['category_id'],trim($_POST['name']),trim($_POST['description']??''),(int)$_POST['price'],(int)$_POST['sort_order']]);if($a==='toggle')$p->prepare("UPDATE services SET is_active=1-is_active WHERE id=?")->execute([(int)$_POST['id']]);if($a==='del')$p->prepare("DELETE FROM services WHERE id=?")->execute([(int)$_POST['id']]);}$cats=$p->query("SELECT id,name FROM categories ORDER BY sort_order,id")->fetchAll();$rows=$p->query("SELECT s.*,c.name cn FROM services s JOIN categories c ON c.id=s.category_id ORDER BY s.id DESC")->fetchAll();?><!doctype html><html lang=fa dir=rtl><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>خدمات</title><style>body{font-family:Tahoma;background:#f4f8fc}.wrap{max-width:1100px;margin:30px auto}.card{background:#fff;padding:22px;border-radius:18px;margin:15px 0}input,textarea,select{width:100%;box-sizing:border-box;padding:11px;margin:7px 0}button{background:#1687d9;color:#fff;border:0;padding:10px 14px;border-radius:8px}.danger{background:#d9534f}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #eee}</style><div class=wrap><a href=/admin/index.php>← داشبورد</a><div class=card><h3>➕ افزودن خدمت</h3><form method=post><input type=hidden name=csrf value="<?=e(csrf())?>"><input type=hidden name=a value=add><select name=category_id required><?php foreach($cats as $c):?><option value=<?=$c['id']?>><?=e($c['name'])?></option><?php endforeach;?></select><input name=name placeholder="نام خدمت" required><textarea name=description placeholder="توضیحات"></textarea><input type=number name=price min=0 placeholder="قیمت تومان" required><input type=number name=sort_order value=0><button>افزودن</button></form></div><div class=card><table><tr><th>خدمت</th><th>دسته</th><th>قیمت</th><th>وضعیت</th><th>فیلدها</th><th>عملیات</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['cn'])?></td><td><?=money((int)$r['price'])?></td><td><?=$r['is_active']?'فعال':'خاموش'?></td><td><a href="/admin/fields.php?service=<?=$r['id']?>">مدیریت</a></td><td><form method=post style="display:inline"><input type=hidden name=csrf value="<?=e(csrf())?>"><input type=hidden name=a value=toggle><input type=hidden name=id value=<?=$r['id']?>><button>تغییر</button></form> <form method=post style="display:inline" onsubmit="return confirm('حذف؟')"><input type=hidden name=csrf value="<?=e(csrf())?>"><input type=hidden name=a value=del><input type=hidden name=id value=<?=$r['id']?>><button class=danger>حذف</button></form></td></tr><?php endforeach;?></table></div></div>
